#!/bin/bash
# Railway wrapper for Onetime Secret: optional first-run admin, then the
# image's own entrypoint (Puma on $PORT).
set -euo pipefail

if [ -z "${SECRET:-}" ]; then
  echo "SECRET is not set; refusing to start (it encrypts every stored secret)." >&2
  exit 1
fi

# Optional: create an admin ("colonel") account on first start.
# Set ADMIN_EMAIL (and ADMIN_PASSWORD, generated by the template) to use it.
# If the account already exists, nothing changes. The password is never logged.
if [ -n "${ADMIN_EMAIL:-}" ]; then
  if [ -z "${ADMIN_PASSWORD:-}" ]; then
    echo "ADMIN_EMAIL is set but ADMIN_PASSWORD is empty; skipping admin creation." >&2
  else
    out=$(bin/ots customers create "$ADMIN_EMAIL" --role colonel --password "$ADMIN_PASSWORD" 2>&1) && rc=0 || rc=$?
    if [ "$rc" -eq 0 ]; then
      echo "Created admin account for ADMIN_EMAIL (password: the ADMIN_PASSWORD variable)." >&2
    elif printf '%s' "$out" | grep -q 'already exists'; then
      echo "Admin account for ADMIN_EMAIL already exists; leaving it unchanged." >&2
    else
      echo "Could not create the admin account (exit $rc):" >&2
      printf '%s\n' "$out" | grep -v -i 'password' | tail -n 20 >&2
    fi
  fi
fi

exec bin/entrypoint.sh "$@"
